```groovy
import com.onemonkeylabs.plugin.support.roles.Administrator

class ChecklistComplete extends org.kohsuke.stapler.script.RequiresRoles {
    @Field("JQL")
    String jql

    @Field("Column Name")
    String columnName

    @Field("Checklist Field")
    String checklistField

    def execute() {
        def issues = search(jql)
        for (int I = 0; I < issues.size(); i++) {
            def issue = issues[i]
            def checklistItems = issue.customFieldValue(checklistField) ? : []
            boolean allChecked = true
            checklistItems.each { item ->
                if (!item.done) {
                    allChecked = false
                    return
                }
            }
            issue.transitions.findAll { it.name == columnName }.each { transition ->
                transition.isEnabled = allChecked
            }
        }
    }
}
```

