Here's a JavaScript function that swaps the positions of adjacent words (adjectives in your case) in a given sentence:

```javascript
function swapAdjacentWords(sentence) {
  const words = sentence.split(" ");
  let left = 0;
  let right = 1;

  while (right < words.length) {
    [words[left], words[right]] = [words[right], words[left]];
    left++;
    right++;

    // If we reach the end of the array, start from the beginning again
    if (left === words.length) {
      left = 0;
      right = 1;
    }
  }

  return words.join(" ");
}

// Example usage
const originalSentence = "Beautiful green trees are in the park";
const swappedSentence = swapAdjacentWords(originalSentence);
console.log(swappedSentence); // Output: "Green beautiful trees are in the park"
```

