```cpp
void MatrixView::paintEvent(QPaintEvent *event) {
    Q_UNUSED(event);

    QPainter painter(this);
    int cellWidth = width() / matrix->cols();
    int cellHeight = height() / matrix->rows();

    // Calculate the scaling factor based on the zoom level
    int scaleFactor = std::min(width(), height()) / std::max(matrix->cols() * cellWidth, matrix->rows() * cellHeight);
    cellWidth *= scaleFactor;
    cellHeight *= scaleFactor;

    // Draw the cells
    for (int row = 0; row < matrix->rows(); ++row) {
        for (int col = 0; col < matrix->cols(); ++col) {
            int x = col * cellWidth;
            int y = row * cellHeight;
            QColor color = getCellColor(row, col);
            painter.fillRect(x, y, cellWidth, cellHeight, color);
            painter.drawText(x + cellWidth / 2 - 4, y + cellHeight / 2 - 4, QString::number(matrix->at(row, col)));
        }
    }
}
```

