import { Document, Discriminator, Schema } from '@nestjs/mongoose';
import { FirstSchema, SecondSchema } from './schemas';

@Document({ discriminatorKey: 'type' })
@Discriminator('MyModel')
export abstract class MyModel {
  @Prop()
  type: string;

  constructor(type: string) {
    this.type = type;
  }
}

@MyModel('first')
export class FirstModel extends FirstSchema {}

@MyModel('second')
