Here's a Swift function that identifies and corrects commonly confused homophones:

```swift
let homophones = [
    ("there", "they're", "their"), // Example from passage
    ("accept", "except"),
    ("advice", "advisory"),
    ("affect", "effect"),
    ("complement", "compliment"),
    ("disinterested", "uninterested"),
    ("principal", "principle"),
    ("stationary", "stationery")
]

func replaceHomophones(_ sentence: String) -> String {
    var result = ""

    for word in sentence.split(separator: " ") {
        let lowercasedWord = String(word.lowercased())

        for (correctWord, _, _) in homophones {
            let regex = try! NSRegularExpression(pattern: "\\b\(lowercasedWord)\\b")

            let matches = regex.matches(in: lowercasedWord, options: [], range: NSRange(location: 0, length: lowercasedWord.utf16.count))

            if !matches.isEmpty {
                result += correctWord + " "
                break
            }
        }

        result += "\(word) "
    }

    return result.trimmingCharacters(in: .whitespacesAndNewlines)
}

// Testing
print(replaceHomophones("Their is know weigh too no if yew sea sumthing and it seams too bee too good too bee true. Eye no that its knot aloud too right like that, butt sum people just don't no the write weigh two do it. Weather or not yew no the difference between there, their, and they're, yew can't denigh that its a common mistake. But can yew correct it programmatically using Swift?"))
```

