1. Define a function `bubbleSort` that takes the array and its size as arguments:

```cpp
void bubbleSort(int arr[], int n) {
    bool swapped = true; // flag to track if any elements were swapped
    int end = n - 1; // index of last element

    while (swapped) {
        swapped = false; // initialize swapped to false

        for (int i = 0; i < end; ++i) {
            if (arr[i] > arr[i+1]) { // swap adjacent elements if they are in wrong order
                int temp = arr[i];
                arr[i] = arr[i+1];
                arr[i+1] = temp;
                swapped = true; // set swapped to true since we have swapped some elements
            }
        }

        --end; // decrement end to avoid unnecessary comparisons in next iteration
    }
}
```

