function getNestedValues(obj, path) {
  let currentObj = obj;
  let paths = path.split('.');

  for (let I = 0; I < paths.length - 1; i++) {
    const key = paths[i];
    if (!currentObj[key]) {
      return []; // Return empty array if any nested key is missing
    }
    currentObj = currentObj[key];
  }

  const lastKey = paths[paths.length - 1];
  const values = [];

