    for (const key in currentObj) {
      if (currentObj.hasOwnProperty(key)) {
        const nestedObj = getNestedValues(currentObj[key], `${lastKey}.${key}`);
        values.push(...nestedObj);
      }
    }
  } else {
    values.push(currentObj);
  }

  return values;
}

