# function to extract dates and titles from XML files
extract_xml <- function(file) {
  library(XML)
  doc <- xmlTreeParse(file)
  dates <- unlist(lapply(xpathSApply(doc, "//date"), function(x) as.Date(gsub("T", " ", x), "%Y-%m-%dT%H:%M:%S")))
  titles <- unlist(lapply(xpathSApply(doc, "//title"), xmlValue))
  list(dates = dates, titles = titles)
}

# function to extract years and descriptions from CSV files
extract_csv <- function(file) {
  read.csv(file, header = FALSE) %>%
    separate(V1, into = c("year", "description"), sep = "-") %>%
    mutate(year = as.integer(year)) %>%
    select(year, description)
}

# function to extract years and descriptions from JSON files
extract_json <- function(file) {
  jsonlite::fromJSON(file, simplifyDataFrame = TRUE) %>%
