sources <- list(
  xml_source = list(
    url = "https://example.com/communication-history.xml",
    parse_func = function(x) xmlTreeParse(x),
    extract_func = function(tree) {
      nodes <- xpathSApply(tree, ".//event", function(e) {
        title <- xpathSApply(e, "title/text()")[1]
        year <- as.integer(xpathSApply(e, "year/text()"))
        description <- xpathSApply(e, "description/text()")
        list(title, year, description)
      })
      return(nodes)
    }
  ),
  csv_source = list(
    url = "https://example.com/communication-history.csv",
    parse_func = read.csv,
    extract_func = function(df) {
      events <- df$Event
      years <- as.integer(df$Year)
      descriptions <- df$Description
      list(events, years, descriptions)
    }
  ),
  json_source = list(
    url = "https://example.com/communication-history.json",
    parse_func = function(x) fromJSON(x),
    extract_func = function(data) {
      events <- unlist(lapply(data$Events, function(e) e$Title))
      years <- unlist(lapply(data$Events, function(e) e$Year))
      descriptions <- unlist(lapply(data$Events, function(e) e$Description))
      list(events, years, descriptions)
    }
  )
)
```

In this example, we have three sources: one in XML format (`xml_source`), one in CSV format (`csv_source`), and one in JSON format (`json_source`).

