function generateArray(input) {
  const result = [];
  let currentPosition = 1; // Start with the first position

  for (let I = 0; I < input.length; i++) {
    const item = input[i];
    const randomize = item.randomize;

    if (!randomize) {
      result[item.position - 1] = item;
    } else {
      // Find an empty spot in the array to insert the item
      while (result[currentPosition - 1]) {
