import AsyncStorage from '@react-native-community/async-storage';

const APP_ID = 'YOUR_APP_ID';
const APP_SECRET = 'YOUR_APP_SECRET';

export const initFacebookSDK = () => {
  return AsyncStorage.multiGet(['FBAppId', 'FBAppSecret']).then((storesResult) => {
    const appId = storesResult[0][1] || APP_ID;
    const appSecret = storesResult[1][1] || APP_SECRET;

    if (!global.FBInited) {
      global.FBInited = true;
      require('./RNFBSDK');
      global.FBSDK.initWithAppId(appId);
      if (appSecret) {
        global.FBSDK.setAppSecretProof(true);
        global.FBSDK.setAccessTokenSource(global.FBSDK.AccessTokenSourceType.ServerAuthCode);
        global.FBSDK.setAppSecret(appSecret);
      }
    }
  });
};

export const getAccessToken = () => {
  return new Promise((resolve, reject) => {
    global.FBSDK.login((error, result) => {
      if (error) {
        reject(error);
        return;
      }
      resolve(result.authResponse.accessToken);
    }, {permissions: ['public_profile', 'email']});
  });
};
```

