3. Navigate into your newly created project directory and start the development server by running `npm start` in the terminal. This will open your browser to `http://localhost:3000`.

4. Inside your project folder, create a new file called `App.js` and replace its contents with this code:

```javascript
import React, { Component } from 'react';
import axios from 'axios';

class App extends Component {
  state = {
    template: null,
    responses: []
  };

  componentDidMount() {
    axios.get('http://localhost:8080/template')
      .then(response => {
        const { id, sentente, choices } = response.data;
        this.setState({ template: { id, sentente, choices } });
      })
      .catch(error => console.log(error));
  }

  handleChoiceChange = event => {
    const { name, value } = event.target;
    const { template } = this.state;
    const updatedChoices = { ...template.choices, [name]: value };
    const updatedTemplate = { ...template, choices: updatedChoices };
    this.setState({ template: updatedTemplate });
  };

  handleSubmit = () => {
    const { template } = this.state;
    const { id, sentente } = template;
    const choices = { relevance: template.choices.relevance[0], quantity: template.choices.quantity[0] };
