```typescript
import { Injectable, NestMiddleware } from '@nestjs/common';
import { ExecutionContext, Logger, UnauthorizedException } from '@nestjs/core';
import { Observable } from 'rxjs';

@Injectable()
export class EnvironmentGuard implements NestMiddleware {
  private readonly logger = new Logger(EnvironmentGuard.name);

  public invoke(context: ExecutionContext): Observable<any> | Promise<any> | any {
    const req = context.switchToHttp().getRequest();
    const env = process.env.NODE_ENV;

    // If in development mode, allow all requests
    if (env === 'development') {
      return super.invoke(context);
    }

    // In production mode, only allow authorized requests
    const authHeader = req.headers.authorization;
    const apiKey = process.env.API_KEY;

    if (!authHeader || authHeader !== `Bearer ${apiKey}`) {
      this.logger.log(`Unauthorized request with headers ${JSON.stringify(req.headers)}`);
      throw new UnauthorizedException('Unauthorized');
    }

    return super.invoke(context);
  }
}

// Usage as decorator
@UseGuards(new EnvironmentGuard())
export class MyController {
  constructor() {}

  @Get()
  getData(): string {
    return 'Data';
  }
}
```

The decorator checks the `NODE_ENV` environment variable and returns `false` immediately if it is not set to "production". Otherwise, it extracts the authorization header from the incoming request and compares it against the API key configured via the `process.env.API_KEY`. If they do not match, an `UnauthorizedException` is thrown. If everything is fine, the middleware passes control to the next handler using `super.invoke(context)`.

This middleware can be used as a decorator by wrapping your controller or route handler with `UseGuards()`, passing an instance of the `EnvironmentGuard` class. This ensures that unauthorized requests are blocked automatically, without having to manually check the environment variable in each request handler

Here's the implementation of the decorator:

```typescript
import { Injectable, NestMiddleware } from '@nestjs/common';
import { Observable } from 'rxjs';
import { switchMap } from 'rxjs/operators';

@Injectable()
export class DevelopmentOnlyMiddleware implements NestMiddleware {
  use(req: any, res: any, next: () => Observable<any>): void | Observable<any> {
    const isDevelopment = process.env.NODE_ENV === 'development';

    if (isDevelopment) {
      return next().pipe(switchMap(() => {
        // perform any necessary actions after the request has been handled in development mode
        return Observable.create(() => {});
      }));
    } else {
      return Observable.create(() => {
        // return false to prevent further execution of the request handler
        return false;
      });
    }
  }
}
```

To use this decorator, import `DevelopmentOnlyMiddleware` into your controller or service file, and apply it as a decorator to the method you want to protect:

```typescript
import { Controller } from '@nestjs/common';
import { DevelopmentOnlyMiddleware } from './development-only.middleware';

@Controller('my-controller')
class MyController {
  @UseGuards(AuthGuard)
  @DevelopmentOnlyMiddleware()
  protected myMethod(): void {}
}
```

In this example, we're applying the `DevelopmentOnlyMiddleware` decorator to the protected method. When running the application in development mode (i.e., when `process.env.NODE_ENV` is set to 'development'), the middleware will allow the request to proceed to the protected method. If the application is running in production mode, the middleware will immediately return `false`, preventing further execution of the request handler.

