     "permissions": ["activeTab"],
     "browser_action": {
       "default_title": "Inject Script"
     },
     "background": {
       "scripts": ["background.js"]
     }
   }
   ```

6. In your `background.js` file, add the following code to listen for messages from your popup and inject your script:

   ```javascript
   chrome.runtime.onmessage.addlistener(function(message, sender, sendresponse) {
