        private static Dictionary<string, double[]> ComputeConditionalProbabilities(Dictionary<string, int> wordCountsByCategory)
        {
            var dictionary = new Dictionary<string, double[]>(StringComparer.OrdinalIgnoreCase);

            foreach (var category in wordCountsByCategory.Keys)
            {
                var wordCounts = new List<int>();
                foreach (var word in wordCountsByCategory[category].Keys)
                {
