        return (string) $server->getConnById($uid)->resourceID;
    }, $connected_users);
    $conn->send(json_encode(['type' => 'list-of-users', 'users' => $existing_users]));
});

$server->on('message', function ($msg, $conn) use ($server) {
    // Handle incoming message
