   ```php
   function createSocket() {
       // Set socket options
       $options = array(
           SOCKOPT_TYPE => SOCK_STREAM,
           SOCKOPT_PROTOCOL => IPPROTO_TCP,
           SOCKOPT_RCVTIMEO => array("sec" => 10, "usec" => 0),
           SOCKOPT_SNDTIMEO => array("sec" => 10, "usec" => 0),
       );

       // Create new socket
       $socket = socket_create(AF_INET, SOCK_STREAM, SOL_TCP);

       // Bind socket to localhost and default port (3000)
       socket_bind($socket, "localhost", 3000);

       // Listen on socket with a maximum queue of 5 connections
       socket_listen($socket, 5);

       return $socket;
   }
